mapper.select:
WITH extracted AS ( SELECT r.PATIENT_ID AS patient_id, TO_CHAR(r.STAT_DATE, 'YYYY-MM-DD') AS day_str, AS period, NVL(SUBSTR(r.RCPT_NO, 1, LENGTH(r.RCPT_NO) - NVL(LENGTH(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')), 0)), '#') AS prefix, TO_NUMBER(REGEXP_SUBSTR(r.RCPT_NO, '[0-9]+$')) AS num_part FROM TR_OUTP_FIN_RCPT_ACCT r WHERE r.STAT_DATE BETWEEN #{startDate} AND #{endDate}
AND NVL(r.TOTAL_CHARGES, 0) >= 0
AND r.REFUNDED_RCPT_NO IS NOT NULL AND r.TOTAL_CHARGES < 0
), ordered AS ( SELECT period, CASE WHEN patient_id = LAG(patient_id) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND day_str = LAG(day_str) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND prefix = LAG(prefix) OVER (ORDER BY patient_id, day_str, prefix, num_part) AND num_part = LAG(num_part) OVER (ORDER BY patient_id, day_str, prefix, num_part) + 1 THEN 0 ELSE 1 END AS is_new_visit FROM extracted ) SELECT period AS "period", SUM(is_new_visit) AS "cnt" FROM ordered GROUP BY period ORDER BY period
